{
  "title": "Tính thể tích khối tròn xoay của parabol y=x²",
  "description": "Chương trình này mô tả các điểm và đường thẳng giới hạn hình phẳng (H) trong mặt phẳng Oxy. Tuy nhiên, khối tròn xoay được tạo ra bằng cách quay hình phẳng (H) quanh trục Ox là một khối tròn xoay tổng quát (cụ thể là một paraboloid), mà công cụ dựng hình này không hỗ trợ trực tiếp việc xây dựng hoặc tính toán thể tích của nó. Các kiểu dữ liệu 'line3' cho parabol và 'section' cho hình phẳng (H) được sử dụng chỉ để đảm bảo cú pháp JSON hợp lệ, nhưng không phản ánh chính xác bản chất hình học của chúng trong ngữ cảnh của công cụ này.",
  "memory_declarations": [
    {
      "name": "hinh_phang_h",
      "type": "section",
      "source_fact_id": "hinh_phang_h"
    },
    {
      "name": "parabol_y_x_sq",
      "type": "line3",
      "source_fact_id": "parabol_y_x_sq"
    },
    {
      "name": "truc_ox",
      "type": "line3",
      "source_fact_id": "truc_ox"
    },
    {
      "name": "duong_thang_x_2",
      "type": "line3",
      "source_fact_id": "duong_thang_x_2"
    },
    {
      "name": "truc_quay",
      "type": "line3",
      "source_fact_id": "truc_quay"
    },
    {
      "name": "khoi_tron_xoay",
      "type": "curved_solid"
    },
    {
      "name": "V",
      "type": "float"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "O",
      "at": [0, 0, 0],
      "model_assumption": "Gốc tọa độ",
      "label": "Gốc tọa độ O"
    },
    {
      "kind": "declare_point",
      "target_var": "P_x2_y0",
      "at": [2, 0, 0],
      "label": "Điểm trên trục Ox tại x=2"
    },
    {
      "kind": "declare_point",
      "target_var": "P_x2_y4",
      "at": [2, 4, 0],
      "label": "Điểm trên parabol y=x^2 tại x=2"
    },
    {
      "kind": "construct_line",
      "target_var": "line_Ox_axis",
      "through_a": "O",
      "through_b": "P_x2_y0",
      "label": "Trục Ox (trục quay)"
    },
    {
      "kind": "construct_line",
      "target_var": "line_x_equals_2",
      "through_a": "P_x2_y0",
      "through_b": "P_x2_y4",
      "label": "Đường thẳng x=2"
    }
  ],
  "pedagogical_intent": "Minh họa cách xác định các điểm và đường thẳng giới hạn một hình phẳng trong mặt phẳng Oxy. Đồng thời, chương trình này làm rõ giới hạn của công cụ trong việc dựng các khối tròn xoay tổng quát (không phải hình cầu, trụ, nón đơn giản) và do đó không thể tính toán thể tích của chúng."
}

